//! DTO-envelope CRUD: blanket adapters over the `cgp-orm` resource service.
//!
//! Some callers — a `flutter_rust_bridge` wrapper generated by
//! `proto_dto::frb_crud_service!`, for example — move **one** envelope type
//! through create, update, and list, and want three small methods instead of
//! the raw resource service:
//!
//! | Method | Forwards to | Adds |
//! |---|---|---|
//! | [`CanCreateByDto::create_by_dto`] | [`CanCreateResource::create`] | nothing |
//! | [`CanUpdateDtoById::update_dto_by_id`] | [`CanUpdateResource::update`] | reads the id off the DTO through [`HasId`] |
//! | [`CanListDto::list_dto`] | [`CanListResources::list`] | turns `page` / `size` into a [`PageRequest`] and drops the page metadata |
//!
//! Each trait has exactly one **blanket impl**. A context whose
//! `CreateInput`, `UpdateInput`, and `Output` are all the same `Dto` — an
//! *envelope context* — gets all three methods for free; there is no
//! per-app impl to write, and `cgp-orm` stays unaware of the DTO shape.
//!
//! # Which contexts get which method
//!
//! The three methods appear **together**, and only on envelope contexts.
//! Each blanket impl pins every service type it relies on:
//!
//! | Method | `CreateInput` | `UpdateInput` | `Output` | Also |
//! |---|---|---|---|---|
//! | `create_by_dto` | `Dto` | — | `Dto` | [`CanCreateResource`] |
//! | `update_dto_by_id` | — | `Dto` | `Dto` | [`CanUpdateResource`], `Dto:` [`HasId`] |
//! | `list_dto` | `Dto` | `Dto` | `Dto` | [`CanListResources`] |
//!
//! `list_dto` only *reads* `Output`, but it is deliberately bounded on all
//! three types. It drops the [`Page`](cgp_orm::pagination::Page) metadata
//! (`page`, `size`, `total`) and skips `COUNT(*)`, which is the right
//! trade for an envelope caller that only ever moves `Vec<Dto>`. A context
//! with distinct create / update / output types (`UserApp` and `PostApp`
//! in `examples/blog`) is not such a caller: it does **not** get
//! `list_dto`, and keeps [`CanListResources::list`], which returns the
//! whole page.
//!
//! The only DTO-specific piece is [`HasId`]: a blanket impl cannot see a
//! field named `id`, so the envelope type implements [`HasId`] once, in the
//! crate that owns it.
//!
//! # A missing id
//!
//! [`CanUpdateDtoById::update_dto_by_id`] on a DTO whose [`HasId::id`] is
//! `None` does not touch the database. It raises `cgp-orm`'s existing
//! [`ErrPrimaryKeyUnset`] for the entity's first primary-key column — the
//! same source error the repository raises for an active model with an
//! unset key — so every error policy in this crate already maps it:
//! [`ApiError::PrimaryKeyUnset`](crate::error::ApiError::PrimaryKeyUnset)
//! in process, `400 Bad Request` over REST, and `InvalidArgument` over
//! gRPC. An entity that declares no primary key raises
//! [`ErrMissingPrimaryKey`] instead. Both raisers are already required by
//! `cgp-orm`'s `UpdateEntityById`, so a context built from
//! `RepositoryCrudStack` satisfies the bounds without new wiring.
//!
//! # Example
//!
//! ```ignore
//! use cgp_api::prelude::*;
//!
//! // Once, next to the envelope type:
//! impl HasId for rf_proto::DtoData {
//!     type Id = i32;
//!     fn id(&self) -> Option<i32> {
//!         self.id
//!     }
//! }
//!
//! // Every context whose CreateInput, UpdateInput, and Output are `DtoData`:
//! let (created, _outcome) = folder_app.create_by_dto(dto).await?;
//! let updated = folder_app.update_dto_by_id(created).await?;
//! let first_page = folder_app.list_dto(None, None).await?;
//! ```

use core::future::Future;

use cgp_fork::prelude::*;
use cgp_orm::components::service::{
    CanCreateResource, CanListResources, CanUpdateResource, HasCreateInputType, HasOutputType,
    HasUpdateInputType,
};
use cgp_orm::error::{ErrMissingPrimaryKey, ErrPrimaryKeyUnset};
use cgp_orm::pagination::PageRequest;
use cgp_orm::types::{ColumnOf, HasEntityType, InsertOutcome, PrimaryKeyOf};
use sea_orm::{EntityTrait, Iterable, PrimaryKeyToColumn};

/// A DTO that may carry the primary key of the row it describes.
///
/// Implement it once for the envelope type. `None` means "no id" (a create
/// payload, or a malformed update).
///
/// The orphan rule puts the impl in the crate that defines the envelope
/// type (for a generated protobuf type, the crate that owns the generated
/// code, typically behind an optional `cgp-api` feature).
///
/// ```
/// use cgp_api::prelude::HasId;
///
/// struct TagDto {
///     id: Option<i32>,
///     name: String,
/// }
///
/// impl HasId for TagDto {
///     type Id = i32;
///
///     fn id(&self) -> Option<i32> {
///         self.id
///     }
/// }
///
/// let dto = TagDto { id: Some(7), name: "rust".into() };
/// assert_eq!(dto.id(), Some(7));
/// ```
pub trait HasId {
    /// The id as the DTO stores it.
    ///
    /// [`CanUpdateDtoById`] converts it with `Into` into the context's
    /// [`PrimaryKeyOf`], so an `i32` id works for an `i32` key without a
    /// wrapper, and a newtype id only needs a `From` impl.
    type Id;

    /// The id, or `None` when the DTO does not carry one.
    ///
    /// Called once per update, before the DTO is handed to the service.
    /// Keep it cheap (ids are usually `Copy`).
    fn id(&self) -> Option<Self::Id>;
}

/// Create from a DTO, or return the existing row with the same identity.
///
/// Blanket-implemented for every [`CanCreateResource`] context whose
/// `CreateInput` and `Output` are both `Dto`.
pub trait CanCreateByDto<Dto>: HasErrorType {
    /// Forward to [`CanCreateResource::create`].
    ///
    /// The [`InsertOutcome`] says whether a row was inserted or an existing
    /// identity match was returned. Callers may ignore it.
    fn create_by_dto(
        &self,
        dto: Dto,
    ) -> impl Future<Output = Result<(Dto, InsertOutcome), Self::Error>> + Send;
}

impl<App, Dto> CanCreateByDto<Dto> for App
where
    App: CanCreateResource + HasCreateInputType<CreateInput = Dto> + HasOutputType<Output = Dto>,
{
    fn create_by_dto(
        &self,
        dto: Dto,
    ) -> impl Future<Output = Result<(Dto, InsertOutcome), Self::Error>> + Send {
        self.create(dto)
    }
}

/// Update the row named by the DTO's own id.
///
/// Blanket-implemented for every [`CanUpdateResource`] context whose
/// `UpdateInput` and `Output` are both `Dto`, when `Dto: HasId` and the id
/// converts into the context's primary key.
pub trait CanUpdateDtoById<Dto>: HasErrorType {
    /// Read [`HasId::id`] and forward to [`CanUpdateResource::update`].
    ///
    /// `Ok(None)` when no row has that id. The whole DTO, id included, is
    /// passed on as the update input.
    ///
    /// # Errors
    ///
    /// A DTO without an id raises [`ErrPrimaryKeyUnset`] (see the
    /// [module docs](self#a-missing-id)) before any database call. Otherwise
    /// whatever [`CanUpdateResource::update`] returns.
    fn update_dto_by_id(
        &self,
        dto: Dto,
    ) -> impl Future<Output = Result<Option<Dto>, Self::Error>> + Send;
}

impl<App, Dto> CanUpdateDtoById<Dto> for App
where
    App: CanUpdateResource
        + HasUpdateInputType<UpdateInput = Dto>
        + HasOutputType<Output = Dto>
        + CanRaiseError<ErrPrimaryKeyUnset<ColumnOf<App>>>
        + CanRaiseError<ErrMissingPrimaryKey>
        + Sync,
    <App::Entity as EntityTrait>::PrimaryKey: PrimaryKeyToColumn<Column = ColumnOf<App>> + Iterable,
    Dto: HasId + Send,
    Dto::Id: Into<PrimaryKeyOf<App>>,
{
    async fn update_dto_by_id(&self, dto: Dto) -> Result<Option<Dto>, Self::Error> {
        let Some(id) = dto.id() else {
            return Err(missing_id::<App>());
        };
        self.update(id.into(), dto).await
    }
}

/// The error for an update DTO without an id.
///
/// Reports the first primary-key column in declaration order, as
/// `cgp-orm` does for an active model whose key is unset.
fn missing_id<App>() -> App::Error
where
    App: HasEntityType
        + CanRaiseError<ErrPrimaryKeyUnset<ColumnOf<App>>>
        + CanRaiseError<ErrMissingPrimaryKey>,
    <App::Entity as EntityTrait>::PrimaryKey: PrimaryKeyToColumn<Column = ColumnOf<App>> + Iterable,
{
    match <App::Entity as EntityTrait>::PrimaryKey::iter().next() {
        Some(key) => App::raise_error(ErrPrimaryKeyUnset {
            column: key.into_column(),
        }),
        None => App::raise_error(ErrMissingPrimaryKey::of::<App::Entity>()),
    }
}

/// List one page of DTOs.
///
/// Blanket-implemented for every [`CanListResources`] context whose
/// `CreateInput`, `UpdateInput`, and `Output` are all `Dto` — the same
/// envelope contexts that get [`CanCreateByDto`] and [`CanUpdateDtoById`].
/// Any other context lists through [`CanListResources::list`], which keeps
/// the page metadata (see the [module docs](self#which-contexts-get-which-method)).
pub trait CanListDto<Dto>: HasErrorType {
    /// Build a [`PageRequest`] and forward to [`CanListResources::list`].
    ///
    /// `page` is 1-based and defaults to `1` (`Some(0)` is also the first
    /// page). `size` of `None` or `Some(0)` selects the context's pagination
    /// policy default; sizes above the policy maximum are clamped. Only the
    /// items are returned; the request skips `COUNT(*)` because the total is
    /// dropped anyway.
    fn list_dto(
        &self,
        page: Option<u64>,
        size: Option<u64>,
    ) -> impl Future<Output = Result<Vec<Dto>, Self::Error>> + Send;
}

impl<App, Dto> CanListDto<Dto> for App
where
    App: CanListResources
        + HasCreateInputType<CreateInput = Dto>
        + HasUpdateInputType<UpdateInput = Dto>
        + HasOutputType<Output = Dto>
        + Sync,
{
    async fn list_dto(
        &self,
        page: Option<u64>,
        size: Option<u64>,
    ) -> Result<Vec<Dto>, Self::Error> {
        let page = self.list(dto_page_request(page, size)).await?;
        Ok(page.items)
    }
}

/// `page` / `size` as [`CanListDto::list_dto`] documents them.
fn dto_page_request(page: Option<u64>, size: Option<u64>) -> PageRequest {
    PageRequest::new(page.unwrap_or(1), size.unwrap_or(0)).without_total()
}

#[cfg(all(test, feature = "thiserror"))]
mod tests {
    //! A mock context: the three resource-service components are an
    //! in-memory `Vec`, everything else is the real `cgp-api` wiring
    //! ([`ApiErrors`]), so the tests exercise the blanket impls exactly as
    //! a `RepositoryCrudStack` context would see them.

    use std::sync::Mutex;

    use cgp_fork::core::error::{ErrorRaiserComponent, ErrorTypeProviderComponent};
    use cgp_orm::components::service::{
        CreateInputTypeProviderComponent, CreateResource, CreateResourceComponent, ListResources,
        ListResourcesComponent, OutputTypeProviderComponent, UpdateInputTypeProviderComponent,
        UpdateResource, UpdateResourceComponent,
    };
    use cgp_orm::pagination::Page;
    use cgp_orm::types::EntityTypeProviderComponent;

    use super::*;
    use crate::error::ApiError;
    use crate::presets::ApiErrors;

    mod tag {
        use sea_orm::entity::prelude::*;

        #[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel)]
        #[sea_orm(table_name = "tags")]
        pub struct Model {
            #[sea_orm(primary_key)]
            pub id: i32,
            pub name: String,
        }

        #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
        pub enum Relation {}

        impl ActiveModelBehavior for ActiveModel {}
    }

    mod pair {
        use sea_orm::entity::prelude::*;

        #[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel)]
        #[sea_orm(table_name = "pairs")]
        pub struct Model {
            #[sea_orm(primary_key, auto_increment = false)]
            pub left_id: i32,
            #[sea_orm(primary_key, auto_increment = false)]
            pub right_id: i32,
        }

        #[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
        pub enum Relation {}

        impl ActiveModelBehavior for ActiveModel {}
    }

    /// One envelope for create, update, and output.
    #[derive(Debug, Clone, PartialEq, Eq)]
    struct TagDto {
        id: Option<i32>,
        name: String,
    }

    impl TagDto {
        fn new(id: Option<i32>, name: &str) -> Self {
            Self {
                id,
                name: name.to_owned(),
            }
        }
    }

    impl HasId for TagDto {
        type Id = i32;

        fn id(&self) -> Option<i32> {
            self.id
        }
    }

    #[derive(Default)]
    struct MockApp {
        rows: Mutex<Vec<TagDto>>,
        updates: Mutex<Vec<i32>>,
        requests: Mutex<Vec<PageRequest>>,
    }

    struct MockService;

    #[cgp_provider(CreateResourceComponent)]
    impl CreateResource<MockApp> for MockService {
        async fn create(
            context: &MockApp,
            input: TagDto,
        ) -> Result<(TagDto, InsertOutcome), ApiError> {
            if input.name.is_empty() {
                return Err(ApiError::Message("name is empty".into()));
            }
            let mut rows = context.rows.lock().unwrap();
            if let Some(existing) = rows.iter().find(|row| row.name == input.name) {
                return Ok((existing.clone(), InsertOutcome::Existing));
            }
            let id = i32::try_from(rows.len()).unwrap() + 1;
            let created = TagDto {
                id: Some(id),
                ..input
            };
            rows.push(created.clone());
            Ok((created, InsertOutcome::Inserted))
        }
    }

    #[cgp_provider(UpdateResourceComponent)]
    impl UpdateResource<MockApp> for MockService {
        async fn update(
            context: &MockApp,
            id: i32,
            input: TagDto,
        ) -> Result<Option<TagDto>, ApiError> {
            context.updates.lock().unwrap().push(id);
            let mut rows = context.rows.lock().unwrap();
            Ok(rows.iter_mut().find(|row| row.id == Some(id)).map(|row| {
                row.name = input.name;
                row.clone()
            }))
        }
    }

    #[cgp_provider(ListResourcesComponent)]
    impl ListResources<MockApp> for MockService {
        async fn list(context: &MockApp, request: PageRequest) -> Result<Page<TagDto>, ApiError> {
            context.requests.lock().unwrap().push(request);
            let rows = context.rows.lock().unwrap();
            let size = if request.size == 0 { 2 } else { request.size };
            let skip = usize::try_from(request.page.saturating_sub(1) * size).unwrap();
            Ok(Page {
                items: rows
                    .iter()
                    .skip(skip)
                    .take(usize::try_from(size).unwrap())
                    .cloned()
                    .collect(),
                page: request.page.max(1),
                size,
                total: None,
            })
        }
    }

    delegate_components! {
        #[unchecked]
        MockApp {
            ErrorTypeProviderComponent:
                <ApiErrors as DelegateComponent<ErrorTypeProviderComponent>>::Delegate,
            ErrorRaiserComponent:
                <ApiErrors as DelegateComponent<ErrorRaiserComponent>>::Delegate,
            EntityTypeProviderComponent: UseType<tag::Entity>,
            CreateInputTypeProviderComponent: UseType<TagDto>,
            UpdateInputTypeProviderComponent: UseType<TagDto>,
            OutputTypeProviderComponent: UseType<TagDto>,
            [
                CreateResourceComponent,
                UpdateResourceComponent,
                ListResourcesComponent,
            ]: MockService,
        }
    }

    /// Only the entity and error wiring, to read the missing-id error of a
    /// composite key.
    struct PairApp;

    delegate_components! {
        #[unchecked]
        PairApp {
            ErrorTypeProviderComponent:
                <ApiErrors as DelegateComponent<ErrorTypeProviderComponent>>::Delegate,
            ErrorRaiserComponent:
                <ApiErrors as DelegateComponent<ErrorRaiserComponent>>::Delegate,
            EntityTypeProviderComponent: UseType<pair::Entity>,
        }
    }

    /// A create input that is not the envelope.
    #[derive(Debug)]
    struct CreateTag;

    /// An update input that is not the envelope.
    #[derive(Debug)]
    struct UpdateTag;

    /// `Output = TagDto`, but create and update take their own structs, like
    /// `UserApp` / `PostApp` in `examples/blog`.
    struct SplitApp;

    /// `CreateInput = Output = TagDto`, but a distinct update input: the
    /// update bound alone must keep `list_dto` away.
    struct HalfEnvelopeApp;

    struct EmptyList;

    #[cgp_provider(ListResourcesComponent)]
    impl<App> ListResources<App> for EmptyList
    where
        App: HasOutputType<Output = TagDto> + HasErrorType<Error = ApiError> + Sync,
    {
        async fn list(_context: &App, request: PageRequest) -> Result<Page<TagDto>, ApiError> {
            Ok(Page {
                items: Vec::new(),
                page: request.page.max(1),
                size: request.size,
                total: Some(0),
            })
        }
    }

    delegate_components! {
        #[unchecked]
        SplitApp {
            ErrorTypeProviderComponent:
                <ApiErrors as DelegateComponent<ErrorTypeProviderComponent>>::Delegate,
            ErrorRaiserComponent:
                <ApiErrors as DelegateComponent<ErrorRaiserComponent>>::Delegate,
            EntityTypeProviderComponent: UseType<tag::Entity>,
            CreateInputTypeProviderComponent: UseType<CreateTag>,
            UpdateInputTypeProviderComponent: UseType<UpdateTag>,
            OutputTypeProviderComponent: UseType<TagDto>,
            ListResourcesComponent: EmptyList,
        }
    }

    delegate_components! {
        #[unchecked]
        HalfEnvelopeApp {
            ErrorTypeProviderComponent:
                <ApiErrors as DelegateComponent<ErrorTypeProviderComponent>>::Delegate,
            ErrorRaiserComponent:
                <ApiErrors as DelegateComponent<ErrorRaiserComponent>>::Delegate,
            EntityTypeProviderComponent: UseType<tag::Entity>,
            CreateInputTypeProviderComponent: UseType<TagDto>,
            UpdateInputTypeProviderComponent: UseType<UpdateTag>,
            OutputTypeProviderComponent: UseType<TagDto>,
            ListResourcesComponent: EmptyList,
        }
    }

    /// Fails to compile when `$ty` implements the trait: two candidate
    /// impls make the inferred `_` ambiguous (the `static_assertions`
    /// `assert_not_impl_any!` technique, without the dependency).
    macro_rules! assert_not_impl {
        ($ty:ty: $($bound:tt)+) => {
            const _: fn() = || {
                trait AmbiguousIfImpl<A> {
                    fn some_item() {}
                }
                impl<T: ?Sized> AmbiguousIfImpl<()> for T {}
                struct Invalid;
                impl<T: ?Sized + $($bound)+> AmbiguousIfImpl<Invalid> for T {}
                let _ = <$ty as AmbiguousIfImpl<_>>::some_item;
            };
        };
    }

    // Envelope context: all three methods.
    const _: fn() = || {
        fn envelope<App>()
        where
            App: CanCreateByDto<TagDto> + CanUpdateDtoById<TagDto> + CanListDto<TagDto>,
        {
        }
        envelope::<MockApp>();
    };

    // Not an envelope: the context can list pages, but has no `list_dto`.
    const _: fn() = || {
        fn lists<App: CanListResources>() {}
        lists::<SplitApp>();
        lists::<HalfEnvelopeApp>();
    };
    assert_not_impl!(SplitApp: CanListDto<TagDto>);
    assert_not_impl!(HalfEnvelopeApp: CanListDto<TagDto>);
    assert_not_impl!(SplitApp: CanCreateByDto<TagDto>);
    assert_not_impl!(HalfEnvelopeApp: CanUpdateDtoById<TagDto>);

    #[tokio::test]
    async fn split_context_lists_through_the_page_api() {
        let page = SplitApp.list(PageRequest::new(1, 5)).await.unwrap();
        assert_eq!((page.page, page.size, page.total), (1, 5, Some(0)));
        assert!(page.items.is_empty());
    }

    fn assert_send<F: Future + Send>(future: F) -> F {
        future
    }

    async fn seeded() -> MockApp {
        let app = MockApp::default();
        for name in ["a", "b", "c"] {
            app.create_by_dto(TagDto::new(None, name)).await.unwrap();
        }
        app
    }

    #[tokio::test]
    async fn create_forwards_and_keeps_the_insert_outcome() {
        let app = MockApp::default();
        let (created, outcome) = assert_send(app.create_by_dto(TagDto::new(None, "rust")))
            .await
            .unwrap();
        assert_eq!(created, TagDto::new(Some(1), "rust"));
        assert_eq!(outcome, InsertOutcome::Inserted);

        let (existing, outcome) = app.create_by_dto(TagDto::new(None, "rust")).await.unwrap();
        assert_eq!(existing, created);
        assert_eq!(outcome, InsertOutcome::Existing);
    }

    #[tokio::test]
    async fn create_returns_the_context_error() {
        let app = MockApp::default();
        let error = app.create_by_dto(TagDto::new(None, "")).await.unwrap_err();
        assert!(matches!(error, ApiError::Message(message) if message == "name is empty"));
    }

    #[tokio::test]
    async fn update_reads_the_id_off_the_dto() {
        let app = seeded().await;
        let updated = assert_send(app.update_dto_by_id(TagDto::new(Some(2), "bee")))
            .await
            .unwrap();
        assert_eq!(updated, Some(TagDto::new(Some(2), "bee")));
        assert_eq!(*app.updates.lock().unwrap(), [2]);
    }

    #[tokio::test]
    async fn update_of_an_unknown_id_is_none() {
        let app = seeded().await;
        let updated = app
            .update_dto_by_id(TagDto::new(Some(99), "zzz"))
            .await
            .unwrap();
        assert_eq!(updated, None);
    }

    #[tokio::test]
    async fn update_without_an_id_raises_primary_key_unset_before_the_service() {
        let app = seeded().await;
        let error = app
            .update_dto_by_id(TagDto::new(None, "nope"))
            .await
            .unwrap_err();
        assert!(
            matches!(&error, ApiError::PrimaryKeyUnset { column } if column == "Id"),
            "got {error:?}"
        );
        assert_eq!(error.to_string(), "primary-key field Id is not set");
        assert!(
            app.updates.lock().unwrap().is_empty(),
            "the service must not be called without an id"
        );
    }

    #[test]
    fn missing_id_of_a_composite_key_names_the_first_column() {
        let error = missing_id::<PairApp>();
        assert!(
            matches!(&error, ApiError::PrimaryKeyUnset { column } if column == "LeftId"),
            "got {error:?}"
        );
    }

    #[tokio::test]
    async fn list_defaults_to_the_first_page_and_the_policy_size() {
        let app = seeded().await;
        let items = assert_send(app.list_dto(None, None)).await.unwrap();
        assert_eq!(
            items,
            [TagDto::new(Some(1), "a"), TagDto::new(Some(2), "b")]
        );

        let items = app.list_dto(Some(2), Some(0)).await.unwrap();
        assert_eq!(items, [TagDto::new(Some(3), "c")]);

        let items: Vec<TagDto> = app.list_dto(Some(1), Some(3)).await.unwrap();
        assert_eq!(items.len(), 3);

        assert_eq!(
            *app.requests.lock().unwrap(),
            [
                PageRequest::new(1, 0).without_total(),
                PageRequest::new(2, 0).without_total(),
                PageRequest::new(1, 3).without_total(),
            ]
        );
    }

    #[test]
    fn page_request_mapping() {
        assert_eq!(
            dto_page_request(None, None),
            PageRequest::first().without_total()
        );
        assert_eq!(
            dto_page_request(Some(0), Some(0)),
            PageRequest::new(0, 0).without_total()
        );
        assert_eq!(
            dto_page_request(Some(4), Some(25)),
            PageRequest::new(4, 25).without_total()
        );
        assert!(!dto_page_request(None, None).include_total);
    }
}
